SELECT COUNT(*) AS brand_new_count
FROM nlq.listings
WHERE condition ILIKE 'brand new';

SELECT COUNT(*) AS nintendo_switch_count
FROM nlq.listings
WHERE (title ILIKE '%nintendo switch%' OR description ILIKE '%nintendo switch%');

SELECT COUNT(*) AS total_listings_at_iv
FROM nlq.listings
WHERE meetup_spot ILIKE '%International Village%';

SELECT MAX(rent_price_per_week) AS highest_weekly_rent
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS num_27inch_monitors
FROM nlq.listings
WHERE (title ILIKE '%27%monitor%' OR description ILIKE '%27%monitor%');

SELECT ROUND(100.0 * SUM(CASE WHEN rent_price_per_week IS NOT NULL THEN 1 ELSE 0 END) / COUNT(*)::numeric, 2) AS rentable_percentage
FROM nlq.listings
WHERE category = 'electronics';

SELECT round(percentile_cont(0.5) WITHIN GROUP (ORDER BY rent_price_per_week)::numeric, 2) AS median_weekly_rent
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS pickup_only_count
FROM nlq.listings
WHERE (title ILIKE '%pickup only%' OR description ILIKE '%pickup only%');

SELECT COUNT(*) AS listings_posted_since_oct_1
FROM nlq.listings
WHERE (listed_at AT TIME ZONE 'America/New_York')::date >= DATE '2026-10-01';

SELECT COUNT(*) AS reviews_given
FROM nlq.my_reviews
WHERE direction = 'given';

SELECT COUNT(*) AS five_star_ratings
FROM nlq.my_reviews
WHERE direction = 'received' AND rating = 5;

SELECT COUNT(*) AS reviews_under_4_stars
FROM nlq.my_reviews
WHERE direction = 'received' AND rating < 4;

SELECT COALESCE(SUM(CASE WHEN my_role = 'seller' THEN agreed_price END), 0) - COALESCE(SUM(CASE WHEN my_role = 'buyer' THEN agreed_price END), 0) AS net_earned
FROM nlq.my_deals
WHERE status = 'completed';

SELECT SUM(agreed_price) AS total_revenue
FROM nlq.deals
WHERE deal_type = 'rental' AND status = 'completed';

SELECT COUNT(*) AS declined_purchase_requests
FROM nlq.deals
WHERE deal_type = 'sale' AND status = 'declined';

SELECT COUNT(*) AS total_requested_deals
FROM nlq.deals
WHERE status = 'requested';

SELECT COUNT(*) AS like_new_count
FROM nlq.listings_all
WHERE condition ILIKE 'like_new';

SELECT COUNT(*) AS suspended_accounts
FROM nlq.students
WHERE account_status = 'suspended';

SELECT COUNT(*) AS listings_with_four_photos
FROM nlq.listings_all
WHERE photo_count = 4;

SELECT COUNT(*) AS total_1_star_reviews
FROM nlq.reviews
WHERE rating = 1;

SELECT COUNT(*) AS report_count
FROM nlq.reports
WHERE target_type = 'listing';

SELECT COUNT(*) AS rented_out_count
FROM nlq.listings_all
WHERE status = 'rented_out';

SELECT category, label
FROM nlq.categories
WHERE category_group = 'leisure';

SELECT ROUND(AVG(buyer_message_count)::numeric, 2) AS avg_buyer_messages,
       ROUND(AVG(seller_message_count)::numeric, 2) AS avg_seller_messages
FROM nlq.conversations;

SELECT COUNT(*) AS buyer_more_messages_conversations
FROM nlq.conversations
WHERE buyer_message_count > seller_message_count;

SELECT ROUND(100.0 * SUM(CASE WHEN rating = 5 THEN 1 ELSE 0 END) / COUNT(*)::numeric, 2) AS percent_5stars
FROM nlq.reviews
WHERE reviewer_role = 'buyer';

SELECT ROUND(100.0 * SUM(CASE WHEN status = 'removed' THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_removed
FROM nlq.listings_all
WHERE condition = 'good';

SELECT round(100.0 * SUM(CASE WHEN resolved_at - filed_at <= interval '48 hours' THEN 1 ELSE 0 END) / COUNT(*), 2) AS percent_closed_within_48h
FROM nlq.reports
WHERE status = 'resolved';

select count(*) as students_posted_no_sale
from (
  select seller_id
  from nlq.listings_all
  group by seller_id
) as posted
where seller_id not in (
  select seller_id
  from nlq.deals
  where deal_type = 'sale' and status = 'completed'
);
